Two edits: emit a real target tuple for `target player` in the Map layer, and stop dropping the typed target at the `draw` converter case.

```text
<<<FILE scripts/paragraph/reparse.py
<<<SEARCH
    if verb == 'p_draw':
        # executeDrawEffect only reads effectValue.target "opponent" vs.
        # default controller — "each player"/"target player"/"that player"
        # aren't representable without real per-player targeting.
        n = _amt(args.get('amount'))
        who = (args.get('who') or '').strip()
        if n is None: return None
        if who in ('each opponent', 'target opponent'):
            return ('draw', {'amount': n, 'target': 'opponent'}, None)
        return None
===REPLACE
    if verb == 'p_draw':
        # executeDrawEffect reads effectValue.target "opponent" vs. default
        # controller for the untargeted phrasings. "target player" is a real
        # target instead, carried in the target tuple like the fixed-amount
        # p_gain_life branch — "each player"/"that player" still aren't
        # representable without per-player targeting / reference tracking.
        n = _amt(args.get('amount'))
        who = (args.get('who') or '').strip()
        if n is None: return None
        if who in ('each opponent', 'target opponent'):
            return ('draw', {'amount': n, 'target': 'opponent'}, None)
        if who == 'target player':
            return ('draw', {'amount': n}, {'filter': 'player'})
        return None
>>>END
```

