			case "draw":
				amount := 1
				if v, ok := ability.Value["amount"]; ok {
					if f, ok := v.(float64); ok {
						amount = int(f)
					} else if i, ok := v.(int); ok {
						amount = i
					}
				}
				eff := &game.SpellEffect{Type: "draw", Amount: amount}
				// "Target player draws N." — lift the typed player target onto
				// the SpellEffect so cast-time validation demands a target and
				// the selected player, not the controller, draws. The
				// untargeted phrasings carry no Target and are unaffected.
				if ability.Target != nil && ability.Target.Filter != "" {
					eff.SpellTargetType = game.TargetType(ability.Target.Filter)
				}
				return eff
>>>END
```

Notes:
- `target opponent` / `each opponent` still hit the earlier branch and emit the value-shortcut form with no target, so their converter path is byte-identical (`Target == nil`).
- `each player` and `that player` fall through to `return None` — still honest misses.
- No controller/opponent shortcut was added for `target player`, and no Engine file is touched.

